  function activeSheet(){return state.spreadsheet.sheets[state.spreadsheet.activeSheet]||state.spreadsheet.sheets[0];}
  function cellDisplay(address){const cell=activeSheet().cells[address];if(!cell)return'';const raw=cell.raw??'';if(String(raw).startsWith('=')){try{const value=evaluateFormula(String(raw),activeSheet(),[address]);return typeof value==='number'?Number(value.toFixed(8)):value;}catch(error){return error.code||'#VALOR!';}}return raw;}
